-- AssetVersionRepository.getPhoto
select
  "asset"."id",
  "asset"."originalFileName",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."width",
  "asset"."height",
  "asset"."thumbhash",
  "asset"."isOffline",
  "exif"."fileSizeInByte",
  "exif"."exifImageWidth",
  "exif"."exifImageHeight",
  "exif"."orientation",
  "base"."kind",
  "base"."source",
  "base"."lookUpdatedAt" is not null as "hasLook",
  "base"."lookSourceAssetId" as "lookSourceId",
  "base"."lookSourceModifiedAt" as "lookSourceModifiedAt",
  exists (
    select
      1
    from
      "asset_edit" "e"
    where
      "e"."assetId" = "asset"."id"
  ) as "hasEditorEdits"
from
  "asset"
  left join "asset_exif" as "exif" on "exif"."assetId" = "asset"."id"
  left join "asset_version" as "base" on "base"."versionAssetId" = "asset"."id"
  and "base"."role" = 'base_photo'
where
  "asset"."id" = $1::uuid

-- AssetVersionRepository.getOutdatedLooks
select
  "base"."versionAssetId" as "assetId"
from
  "asset_version" as "base"
  inner join "asset" as "photo" on "photo"."id" = "base"."versionAssetId"
  left join "asset" as "source" on "source"."id" = "base"."lookSourceAssetId"
where
  "base"."role" = $1
  and not exists (
    select
      1
    from
      "asset_edit" "e"
    where
      "e"."assetId" = "base"."versionAssetId"
  )
  and (
    "base"."lookQueuedAt" is null
    or "base"."lookQueuedAt" < now() - interval '1 hour'
  )
  and (
    (
      "base"."lookUpdatedAt" is not null
      and (
        "base"."lookSourceAssetId" is null
        or "base"."lookSourceModifiedAt" is null
        or date_trunc('milliseconds', "source"."fileModifiedAt") <> date_trunc('milliseconds', "base"."lookSourceModifiedAt")
        or "base"."lookSourceAssetId" is distinct from coalesce(
          (
            select
              case
                when "base"."kind" = 'edit'
                and (
                  date_trunc('milliseconds', "photo"."fileModifiedAt"),
                  "photo"."id"
                ) > (
                  date_trunc('milliseconds', "a"."fileModifiedAt"),
                  "a"."id"
                ) then null
                else "a"."id"
              end
            from
              "asset_version" "v"
              inner join "asset" "a" on "a"."id" = "v"."versionAssetId"
            where
              "v"."assetId" = "base"."versionAssetId"
              and "v"."role" = 'version'
              and "v"."kind" = 'edit'
            order by
              date_trunc('milliseconds', "a"."fileModifiedAt") desc,
              "a"."id" desc
            limit
              1
          ),
          (
            select
              "v"."versionAssetId"
            from
              "asset_version" "v"
            where
              "base"."kind" = 'raw'
              and "v"."assetId" = "base"."versionAssetId"
              and "v"."role" = 'version'
              and "v"."kind" = 'original'
            order by
              "v"."versionAssetId"::text
            limit
              1
          )
        )
        or not exists (
          select
            1
          from
            "asset_file" "f"
          where
            "f"."assetId" = "base"."versionAssetId"
            and "f"."isEdited"
            and "f"."type" = 'preview'
        )
      )
    )
    or (
      "base"."lookUpdatedAt" is null
      and coalesce(
        (
          select
            case
              when "base"."kind" = 'edit'
              and (
                date_trunc('milliseconds', "photo"."fileModifiedAt"),
                "photo"."id"
              ) > (
                date_trunc('milliseconds', "a"."fileModifiedAt"),
                "a"."id"
              ) then null
              else "a"."id"
            end
          from
            "asset_version" "v"
            inner join "asset" "a" on "a"."id" = "v"."versionAssetId"
          where
            "v"."assetId" = "base"."versionAssetId"
            and "v"."role" = 'version'
            and "v"."kind" = 'edit'
          order by
            date_trunc('milliseconds', "a"."fileModifiedAt") desc,
            "a"."id" desc
          limit
            1
        ),
        (
          select
            "v"."versionAssetId"
          from
            "asset_version" "v"
          where
            "base"."kind" = 'raw'
            and "v"."assetId" = "base"."versionAssetId"
            and "v"."role" = 'version'
            and "v"."kind" = 'original'
          order by
            "v"."versionAssetId"::text
          limit
            1
        )
      ) is not null
    )
  )
  and "base"."versionAssetId" > $2::uuid
order by
  "base"."versionAssetId"
limit
  $3

