-- AssetVersionRepository.getSidecarPaths
select
  "asset_file"."assetId",
  "asset_file"."path"
from
  "asset_file"
where
  "asset_file"."assetId" in ($1)
  and "asset_file"."type" = $2

-- AssetVersionRepository.getVersionFile
select
  "asset_file"."path"
from
  "asset_file"
where
  "asset_file"."assetId" = $1::uuid
  and "asset_file"."type" = $2
  and "asset_file"."isEdited" = $3

-- AssetVersionRepository.getOrphans
select
  "asset"."id",
  "asset"."libraryId"
from
  "asset_version" as "v"
  inner join "asset" on "asset"."id" = "v"."versionAssetId"
where
  "v"."role" = $1
  and "v"."assetId" is null
  and (
    "v"."cleanupQueuedAt" is null
    or "v"."cleanupQueuedAt" < now() - interval '1 hour'
  )
limit
  $2

-- AssetVersionRepository.getUnsynced
select
  "v"."versionAssetId"
from
  "asset_version" as "v"
where
  "v"."role" = $1
  and "v"."syncedAt" is null
  and "v"."versionAssetId" > $2
order by
  "v"."versionAssetId"
limit
  $3

-- AssetVersionRepository.streamForThumbnails
select
  "v"."versionAssetId" as "id"
from
  "asset_version" as "v"
where
  "v"."role" = $1
  and "v"."assetId" is not null
  and (
    not exists (
      select
        "asset_file"."id"
      from
        "asset_file"
      where
        "asset_file"."assetId" = "v"."versionAssetId"
        and "asset_file"."type" = $2
    )
    or not exists (
      select
        "asset_file"."id"
      from
        "asset_file"
      where
        "asset_file"."assetId" = "v"."versionAssetId"
        and "asset_file"."type" = $3
    )
  )

-- AssetVersionRepository.getPhotosWithVersions
select distinct
  "assetId"
from
  "asset_version"
where
  "role" = $1
  and "assetId" is not null
limit
  $2
